import { clampIsiMs } from './isi';

/** Match % threshold to promote one ladder step. */
export const PROMOTE_MATCH_PCT = 80;

/** Consecutive fails below promote threshold before demoting one step. */
export const FAILS_TO_DEMOTE = 3;

/** Interference when a level turns it on (free-play default ⅛). */
export const PROGRESS_INTERFERENCE_ON = 0.125;

/** Highest session N generated by the repeating 10-step recipe. */
export const PROGRESS_MAX_N = 9;

/** Steps per N before advancing to n+1. */
export const STEPS_PER_N = 10;

export type ProgressLevel = {
    n: number;
    isiMin: number;
    isiMax: number;
    interferenceChance: number;
    variableN: boolean;
};

export type ProgressionAction = 'promote' | 'demote' | 'hold';

export type ProgressionDecision = {
    action: ProgressionAction;
    levelIndex: number;
    failStreak: number;
    reason: string;
};

type StepRecipe = {
    isiBaseMs: number;
    variableIsi: boolean;
    interference: boolean;
    variableN: boolean;
};

/** Per-n recipe (step 0…9), then n+1 restarts at step 0. */
const STEP_RECIPES: readonly StepRecipe[] = [
    { isiBaseMs: 2500, variableIsi: false, interference: false, variableN: false },
    { isiBaseMs: 2500, variableIsi: false, interference: true, variableN: false },
    { isiBaseMs: 2000, variableIsi: false, interference: true, variableN: false },
    { isiBaseMs: 1500, variableIsi: false, interference: true, variableN: false },
    { isiBaseMs: 1000, variableIsi: false, interference: true, variableN: false },
    { isiBaseMs: 1000, variableIsi: true, interference: true, variableN: false },
    { isiBaseMs: 2000, variableIsi: false, interference: true, variableN: true },
    { isiBaseMs: 1500, variableIsi: false, interference: true, variableN: true },
    { isiBaseMs: 1000, variableIsi: false, interference: true, variableN: true },
    { isiBaseMs: 1000, variableIsi: true, interference: true, variableN: true },
];

function isiRangeFromRecipe(recipe: StepRecipe): { isiMin: number; isiMax: number } {
    if (!recipe.variableIsi) {
        const fixed = clampIsiMs(recipe.isiBaseMs);
        return { isiMin: fixed, isiMax: fixed };
    }
    return {
        isiMin: clampIsiMs(recipe.isiBaseMs * 0.9),
        isiMax: clampIsiMs(recipe.isiBaseMs * 1.1),
    };
}

function levelFromNAndStep(n: number, step: number): ProgressLevel {
    const recipe = STEP_RECIPES[step] ?? STEP_RECIPES[0];
    const { isiMin, isiMax } = isiRangeFromRecipe(recipe);
    return {
        n,
        isiMin,
        isiMax,
        interferenceChance: recipe.interference ? PROGRESS_INTERFERENCE_ON : 0,
        variableN: recipe.variableN,
    };
}

/** Global index = (n - 2) * 10 + step. */
export function maxLevelIndex(): number {
    return (PROGRESS_MAX_N - 2) * STEPS_PER_N + (STEPS_PER_N - 1);
}

export function clampLevelIndex(index: number): number {
    if (!Number.isFinite(index)) return 0;
    return Math.max(0, Math.min(maxLevelIndex(), Math.floor(index)));
}

export function levelAt(index: number): ProgressLevel {
    const clamped = clampLevelIndex(index);
    const n = 2 + Math.floor(clamped / STEPS_PER_N);
    const step = clamped % STEPS_PER_N;
    return levelFromNAndStep(n, step);
}

/** Alias used by store/persistence when applying ladder → settings. */
export function settingsFromLevel(index: number): ProgressLevel {
    return levelAt(index);
}

export function stepWithinN(index: number): number {
    return clampLevelIndex(index) % STEPS_PER_N;
}

export function decideProgression(input: {
    levelIndex: number;
    failStreak: number;
    matchPct: number;
}): ProgressionDecision {
    const levelIndex = clampLevelIndex(input.levelIndex);
    const failStreak = Math.max(0, Math.floor(input.failStreak));
    const matchPct = Number.isFinite(input.matchPct) ? input.matchPct : 0;
    const ceiling = maxLevelIndex();

    if (matchPct >= PROMOTE_MATCH_PCT) {
        if (levelIndex >= ceiling) {
            return {
                action: 'hold',
                levelIndex,
                failStreak: 0,
                reason: `Match ${matchPct}% ≥ ${PROMOTE_MATCH_PCT}% but already at max level`,
            };
        }
        return {
            action: 'promote',
            levelIndex: levelIndex + 1,
            failStreak: 0,
            reason: `Match ${matchPct}% ≥ ${PROMOTE_MATCH_PCT}% — promote one level`,
        };
    }

    const nextFail = failStreak + 1;
    if (nextFail >= FAILS_TO_DEMOTE) {
        if (levelIndex <= 0) {
            return {
                action: 'hold',
                levelIndex: 0,
                failStreak: 0,
                reason: `Fail streak ${nextFail} at minimum level — reset streak`,
            };
        }
        return {
            action: 'demote',
            levelIndex: levelIndex - 1,
            failStreak: 0,
            reason: `${FAILS_TO_DEMOTE} fails in a row — demote one level`,
        };
    }

    return {
        action: 'hold',
        levelIndex,
        failStreak: nextFail,
        reason: `Match ${matchPct}% < ${PROMOTE_MATCH_PCT}% — fail ${nextFail}/${FAILS_TO_DEMOTE}`,
    };
}
